// Requirement — the rule, no logic
public record MinimumTenureRequirement(int Years) : IAuthorizationRequirement;

// Handler — the logic, resolved from DI
public class MinimumTenureHandler
    : AuthorizationHandler<MinimumTenureRequirement>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        MinimumTenureRequirement requirement)
    {
        var since = context.User.FindFirst("member_since")?.Value;
        if (since is not null &&
            DateTime.UtcNow.Year - int.Parse(since) >= requirement.Years)
        {
            context.Succeed(requirement);
        }
        // Note: no context.Fail() — failing one handler must not
        // block other requirements' handlers from succeeding.
    }
}

// Program.cs
builder.Services.AddSingleton<IAuthorizationHandler, MinimumTenureHandler>();
builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("TenuredEmployee", policy =>
        policy.RequireRole("Employee")
              .Requirements.Add(new MinimumTenureRequirement(2)));

    // Requests without an identity must satisfy this policy by default
    options.FallbackPolicy = new AuthorizationPolicyBuilder()
        .RequireAuthenticatedUser()
        .Build();
});

// Usage
[Authorize(Policy = "TenuredEmployee")]
[HttpGet("payroll")]
public IActionResult Payroll() => Ok();
